-- DEMO PROVIDER ONLY. Refused when a company is live. Never used with real data.
CREATE TABLE IF NOT EXISTS stub_account (ref TEXT PRIMARY KEY, tenant TEXT NOT NULL, balance INTEGER NOT NULL DEFAULT 0, earned INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS stub_entry (id TEXT PRIMARY KEY, idem TEXT UNIQUE, ref TEXT NOT NULL, kind TEXT NOT NULL, amount INTEGER NOT NULL, extra TEXT, at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS stub_hold (id TEXT PRIMARY KEY, tenant TEXT NOT NULL, ref TEXT, amount INTEGER NOT NULL, remaining INTEGER NOT NULL, kind TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'open');
